                int row0 = _shfl_0;
                int _shfl_1 = __shfl_sync(0xFFFFFFFF, lane_token_up, 4);
                int row1 = _shfl_1;
                int _shfl_2 = __shfl_sync(0xFFFFFFFF, lane_token_up, 8);
                int row2 = _shfl_2;
                int _shfl_3 = __shfl_sync(0xFFFFFFFF, lane_token_up, 12);
                int row3 = _shfl_3;
                int _shfl_4 = __shfl_sync(0xFFFFFFFF, lane_token_up, 16);
                int row4 = _shfl_4;
                int _shfl_5 = __shfl_sync(0xFFFFFFFF, lane_token_up, 20);
                int row5 = _shfl_5;
                int _shfl_6 = __shfl_sync(0xFFFFFFFF, lane_token_up, 24);
                int row6 = _shfl_6;
                int _shfl_7 = __shfl_sync(0xFFFFFFFF, lane_token_up, 28);
                int row7 = _shfl_7;
                int _shfl_8 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 0);
                int row8 = _shfl_8;
                int _shfl_9 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 4);
                int row9 = _shfl_9;
                int _shfl_10 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 8);
                int row10 = _shfl_10;
                int _shfl_11 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 12);
                int row11 = _shfl_11;
                int _shfl_12 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 16);
                int row12 = _shfl_12;
                int _shfl_13 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 20);
                int row13 = _shfl_13;
                int _shfl_14 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 24);
                int row14 = _shfl_14;
                int _shfl_15 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 28);
                int row15 = _shfl_15;
                unsigned int up_stage = 0;
                #pragma unroll 1
                for (int kb = 0; kb < K / 256; kb++) {
                    mbarrier_wait(up_free_addr + (up_stage) * 8, _phase_up_free);
                    if (elect_sync()) {
                        mbarrier_arrive_expect_tx(up_full_addr + (up_stage) * 8, 38912);
                        tma_3d_gmem2smem(smem_w1_gate_sf_addr + up_stage * 40960, (&w1_scale_prepared), 0, 0, (expert * (2 * intermediate_blocks) + intermediate_block) * (K / 256) + kb, up_full_addr + (up_stage) * 8);
                        tma_3d_gmem2smem(smem_w1_up_sf_addr + up_stage * 40960, (&w1_scale_prepared), 0, 0, (expert * (2 * intermediate_blocks) + intermediate_blocks + intermediate_block) * (K / 256) + kb, up_full_addr + (up_stage) * 8);
                        tma_gather4_gmem2smem(smem_x_addr + up_stage * 40960, (&x), kb * 128, row0, row1, row2, row3, up_full_addr + (up_stage) * 8);
                        tma_gather4_gmem2smem(smem_x_addr + up_stage * 40960 + 512, (&x), kb * 128, row4, row5, row6, row7, up_full_addr + (up_stage) * 8);
                        tma_gather4_gmem2smem(smem_x_addr + up_stage * 40960 + 1024, (&x), kb * 128, row8, row9, row10, row11, up_full_addr + (up_stage) * 8);
                        tma_gather4_gmem2smem(smem_x_addr + up_stage * 40960 + 1536, (&x), kb * 128, row12, row13, row14, row15, up_full_addr + (up_stage) * 8);
                        tma_4d_gmem2smem(smem_w1_addr + up_stage * 40960, (&W1), 0, intermediate_block * 128, kb, expert, up_full_addr + (up_stage) * 8);
                        tma_4d_gmem2smem(smem_w1_addr + up_stage * 40960 + 16384, (&W1), 0, intermediate_blocks * 128 + intermediate_block * 128, kb, expert, up_full_addr + (up_stage) * 8);
                    }
                    up_stage += 1;
                    if (up_stage == 2) { up_stage = 0; _phase_up_free ^= 1; }
