                asm volatile("barrier.sync 14, 192;" ::: "memory");
            }
        }
    }
    // ---- Role: mma ----
    if (warp == 1) {
        { // mma_main
            int route_base_m = blockIdx.x * 8;
            int route_extent_m = num_tokens_post_padded[0];
            bool owns_route_m = route_base_m < route_extent_m;
            bool pair_upper_m = 0;
            int route_expert_m = 0;
            if (owns_route_m) {
                int current_route_block_m = route_base_m / route_block_m;
                route_expert_m = expert_ids[current_route_block_m];
                int subtiles_per_block_m = route_block_m / 8;
                int pair_position_m = blockIdx.x;
                if (subtiles_per_block_m % 2 != 0) {
                    int run_first_block_m = current_route_block_m;
                    #pragma unroll 1
                    for (int run_chunk_m = 0; run_chunk_m < (current_route_block_m + 32) / 32; run_chunk_m++) {
                        int probe_block_m = (unsigned int)(current_route_block_m - 1 - run_chunk_m * 32) - lane;
                        bool at_boundary_m = 1;
                        if (probe_block_m >= 0) {
                            int probe_expert_m = expert_ids[probe_block_m];
                            at_boundary_m = probe_expert_m != route_expert_m;
                        }
                        unsigned int _vote_1 = __ballot_sync(0xFFFFFFFF, at_boundary_m);
                        unsigned int boundary_mask_m = _vote_1;
                        if (boundary_mask_m != 0) {
                            int _ffs_1 = __ffs(boundary_mask_m);
                            int first_boundary_lane_m = _ffs_1 - 1;
                            run_first_block_m = current_route_block_m - run_chunk_m * 32 - first_boundary_lane_m;
                            break;
                        }
                    }
                    pair_position_m = blockIdx.x - run_first_block_m * subtiles_per_block_m;
                }
                if (pair_position_m % 2 == 0) {
                    if (route_extent_m > route_base_m + 8) {
                        int next_expert_m = expert_ids[(route_base_m + 8) / route_block_m];
                        pair_upper_m = next_expert_m == route_expert_m;
                    }
                } else {
                    owns_route_m = 0;
                }
            }
            unsigned int _phase_up_full = 0;
            if (owns_route_m) {
                unsigned int up_stage_mma = 0;
                #pragma unroll 1
                for (int kb_mma = 0; kb_mma < K / 256; kb_mma++) {
                    mbarrier_wait(up_full_addr + (up_stage_mma) * 8, _phase_up_full);
                    asm volatile("tcgen05.fence::after_thread_sync;");
                    asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
                    if (elect_sync()) {
                        tcgen05_cp_32x128b_warpx4(tmem_up_gate_sf, make_sf_cp_desc_lo_sbo512((((smem_w1_gate_sf_addr) >> 4) + (up_stage_mma) * 2560)));
                        tcgen05_cp_32x128b_warpx4((tmem_up_gate_sf + 4), make_sf_cp_desc_lo_sbo512((((smem_w1_gate_sf_addr) >> 4) + (up_stage_mma) * 2560 + 8)));
                        tcgen05_cp_32x128b_warpx4((tmem_up_gate_sf + 8), make_sf_cp_desc_lo_sbo512((((smem_w1_gate_sf_addr) >> 4) + (up_stage_mma) * 2560 + 16)));
                        tcgen05_cp_32x128b_warpx4((tmem_up_gate_sf + 12), make_sf_cp_desc_lo_sbo512((((smem_w1_gate_sf_addr) >> 4) + (up_stage_mma) * 2560 + 24)));
                    }
                    if (elect_sync()) {
                        tcgen05_cp_32x128b_warpx4(tmem_up_up_sf, make_sf_cp_desc_lo_sbo512((((smem_w1_up_sf_addr) >> 4) + (up_stage_mma) * 2560)));
                        tcgen05_cp_32x128b_warpx4((tmem_up_up_sf + 4), make_sf_cp_desc_lo_sbo512((((smem_w1_up_sf_addr) >> 4) + (up_stage_mma) * 2560 + 8)));
                        tcgen05_cp_32x128b_warpx4((tmem_up_up_sf + 8), make_sf_cp_desc_lo_sbo512((((smem_w1_up_sf_addr) >> 4) + (up_stage_mma) * 2560 + 16)));
                        tcgen05_cp_32x128b_warpx4((tmem_up_up_sf + 12), make_sf_cp_desc_lo_sbo512((((smem_w1_up_sf_addr) >> 4) + (up_stage_mma) * 2560 + 24)));
                    }
                    if (elect_sync()) {
                        tcgen05_cp_32x128b_warpx4(tmem_up_x_sf, make_sf_cp_desc_lo_sbo512((((smem_x_sf_addr) >> 4) + (up_stage_mma) * 2560)));
                        tcgen05_cp_32x128b_warpx4((tmem_up_x_sf + 4), make_sf_cp_desc_lo_sbo512((((smem_x_sf_addr) >> 4) + (up_stage_mma) * 2560 + 8)));
                        tcgen05_cp_32x128b_warpx4((tmem_up_x_sf + 8), make_sf_cp_desc_lo_sbo512((((smem_x_sf_addr) >> 4) + (up_stage_mma) * 2560 + 16)));
                        tcgen05_cp_32x128b_warpx4((tmem_up_x_sf + 12), make_sf_cp_desc_lo_sbo512((((smem_x_sf_addr) >> 4) + (up_stage_mma) * 2560 + 24)));
                    }
                    int init_up = ((kb_mma == 0) ? 1 : 0);
                    int _mma_a_lo_0 = make_warp_uniform((((smem_w1_addr) >> 4) & 0x3FFF) + (up_stage_mma) * 2560);
                    int _mma_b_lo_0 = make_warp_uniform((((smem_x_addr) >> 4) & 0x3FFF) + (up_stage_mma) * 2560);
                    if (elect_sync()) {
                        {
                            uint64_t a_desc = ((uint64_t)(uint32_t)_mma_a_lo_0) | ((uint64_t)0x40004040 << 32);
                            uint64_t b_desc = ((uint64_t)(uint32_t)_mma_b_lo_0) | ((uint64_t)0x40004040 << 32);

                            tcgen05_mma_mxf4nvf4_bs(tmem_up_acc, a_desc + 0, b_desc + 0,
                                0x8040480U, tmem_up_gate_sf + 0, tmem_up_x_sf + 0, ((init_up) ? 0 : 1));
                            tcgen05_mma_mxf4nvf4_bs(tmem_up_acc, a_desc + 2, b_desc + 2,
                                0x8040480U, tmem_up_gate_sf + 4, tmem_up_x_sf + 4, 1);
                            tcgen05_mma_mxf4nvf4_bs(tmem_up_acc, a_desc + 4, b_desc + 4,
                                0x8040480U, tmem_up_gate_sf + 8, tmem_up_x_sf + 8, 1);
                            tcgen05_mma_mxf4nvf4_bs(tmem_up_acc, a_desc + 6, b_desc + 6,
                                0x8040480U, tmem_up_gate_sf + 12, tmem_up_x_sf + 12, 1);
                        }
                    }
                    int _mma_a_lo_1 = make_warp_uniform((((smem_w1_addr + 16384) >> 4) & 0x3FFF) + (up_stage_mma) * 2560);
                    int _mma_b_lo_1 = make_warp_uniform((((smem_x_addr) >> 4) & 0x3FFF) + (up_stage_mma) * 2560);
                    if (elect_sync()) {
                        {
                            uint64_t a_desc = ((uint64_t)(uint32_t)_mma_a_lo_1) | ((uint64_t)0x40004040 << 32);
                            uint64_t b_desc = ((uint64_t)(uint32_t)_mma_b_lo_1) | ((uint64_t)0x40004040 << 32);

                            tcgen05_mma_mxf4nvf4_bs((tmem_up_acc + (16)), a_desc + 0, b_desc + 0,
                                0x8040480U, tmem_up_up_sf + 0, tmem_up_x_sf + 0, ((init_up) ? 0 : 1));
