namespace flashinfer {
namespace alphamoe_nvfp4_sm100 {

void AlignAndSeedOutputGeneral(TensorView topk_ids, int64_t num_experts, int64_t block_size,
                    TensorView sorted_token_ids, TensorView expert_ids,
                    TensorView num_tokens_post_padded, TensorView cumsum_buffer,
                    TensorView initial_out, TensorView seeded_accumulator,
                    bool pad_sorted_token_ids) {
  TVM_FFI_ICHECK(topk_ids.device().device_type == kDLCUDA)
      << "topk_ids must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(topk_ids.device().device_id);
  CheckSm100OrSm103(topk_ids.device().device_id);
  CheckTensor(topk_ids, dl_int32, 2, true, "topk_ids", "int32");
  CheckTensor(sorted_token_ids, dl_int32, 1, true, "sorted_token_ids", "int32");
  CheckTensor(expert_ids, dl_int32, 1, true, "expert_ids", "int32");
  CheckTensor(num_tokens_post_padded, dl_int32, 1, true, "num_tokens_post_padded", "int32");
  CheckTensor(cumsum_buffer, dl_int32, 1, true, "cumsum_buffer", "int32");
  CheckTensor(initial_out, dl_bfloat16, 2, true, "initial_out", "bfloat16");
  CheckTensor(seeded_accumulator, dl_float32, 2, true, "seeded_accumulator", "float32");
  const int device_id = topk_ids.device().device_id;
  CheckSameDevice(initial_out, device_id, "initial_out");
  CheckSameDevice(seeded_accumulator, device_id, "seeded_accumulator");
  TVM_FFI_ICHECK(initial_out.size(0) == topk_ids.size(0) && initial_out.size(1) > 0)
      << "initial_out must have the route row count and a positive output width";
  CheckShape2(seeded_accumulator, initial_out.size(0), initial_out.size(1),
              "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, initial_out, "initial_out", "seeded_accumulator");
  CheckSameDevice(sorted_token_ids, device_id, "sorted_token_ids");
  CheckSameDevice(expert_ids, device_id, "expert_ids");
  CheckSameDevice(num_tokens_post_padded, device_id, "num_tokens_post_padded");
  CheckSameDevice(cumsum_buffer, device_id, "cumsum_buffer");
  TVM_FFI_ICHECK(topk_ids.size(0) > 0 && topk_ids.size(1) > 0 && topk_ids.numel() <= kIntMax)
      << "topk_ids must have positive dimensions and fit int32 indexing";
  TVM_FFI_ICHECK(num_experts > 1 && num_experts <= 1024)
      << "num_experts must include the reserved bin and lie in [2, 1024]";
  TVM_FFI_ICHECK(block_size == 8 || block_size == 16) << "block_size must be 8 or 16";
  TVM_FFI_ICHECK(pad_sorted_token_ids) << "full-capacity sorted-token padding is required";
  const int64_t pairs = topk_ids.numel();
  // Same valid-expert domain and tight worst-case plan bound as aligned compute.
  // Reserved-bin negative IDs are not valid routed compute inputs.
  const int64_t nonempty = (num_experts - 1 < pairs) ? num_experts - 1 : pairs;
  const int64_t max_blocks = nonempty + (pairs - nonempty) / block_size;
  TVM_FFI_ICHECK(sorted_token_ids.numel() >= max_blocks * block_size &&
                 sorted_token_ids.numel() <= kIntMax)
      << "sorted_token_ids must cover every padded valid-expert route and fit int32";
  TVM_FFI_ICHECK(expert_ids.numel() >= max_blocks)
      << "expert_ids must cover every possible used valid-expert block";
  TVM_FFI_ICHECK(num_tokens_post_padded.numel() == 1)
      << "num_tokens_post_padded must have one entry";
  TVM_FFI_ICHECK(cumsum_buffer.numel() >= num_experts + 1)
      << "cumsum_buffer must cover all bins and the final extent";
  CheckNoOverlap(initial_out, topk_ids, "topk_ids", "initial_out");
  CheckNoOverlap(initial_out, sorted_token_ids, "sorted_token_ids", "initial_out");
  CheckNoOverlap(initial_out, expert_ids, "expert_ids", "initial_out");
  CheckNoOverlap(initial_out, num_tokens_post_padded, "num_tokens_post_padded", "initial_out");
  CheckNoOverlap(initial_out, cumsum_buffer, "cumsum_buffer", "initial_out");
  CheckNoOverlap(seeded_accumulator, topk_ids, "topk_ids", "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, sorted_token_ids, "sorted_token_ids", "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, expert_ids, "expert_ids", "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, num_tokens_post_padded, "num_tokens_post_padded", "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, cumsum_buffer, "cumsum_buffer", "seeded_accumulator");
  const cudaStream_t stream = get_stream(topk_ids.device());
  const int64_t output_numel = initial_out.numel();
  const unsigned int seed_ctas = static_cast<unsigned int>((output_numel + 1023) / 1024);
  nvfp4_route_alignment_seed::kernel_alpha_moe_route_alignment_seed_public<<<
      dim3(seed_ctas + 1, 1, 1), dim3(nvfp4_route_alignment_seed::kAlignmentThreads, 1, 1),
      nvfp4_route_alignment_seed::kAlignmentSmemTotal, stream>>>(
          static_cast<int*>(topk_ids.data_ptr()),
          static_cast<int*>(sorted_token_ids.data_ptr()),
          static_cast<int*>(expert_ids.data_ptr()),
          static_cast<int*>(num_tokens_post_padded.data_ptr()),
          static_cast<int*>(cumsum_buffer.data_ptr()),
          static_cast<__nv_bfloat16*>(initial_out.data_ptr()),
          static_cast<float*>(seeded_accumulator.data_ptr()),
          static_cast<int>(num_experts), static_cast<int>(block_size),
          static_cast<int>(pairs), static_cast<int>(sorted_token_ids.numel()),
          static_cast<long long>(output_numel));
  CheckCuda(cudaGetLastError(), "alphamoe_nvfp4_align_and_seed_output kernel launch");
}

void RunRoutedSeededGeneral(
    TensorView hidden_states, TensorView hidden_states_scale, TensorView gemm1_weights,
    TensorView gemm1_weights_scale, TensorView gemm2_weights, TensorView gemm2_weights_scale,
    TensorView output1_scale_gate_scalar, TensorView output1_scale_scalar,
    TensorView output2_scale_scalar, TensorView sorted_token_ids, TensorView expert_ids,
    TensorView num_tokens_post_padded, TensorView topk_weights, TensorView out,
    TensorView accumulator, TensorView topk_ids, TensorView cumsum_buffer,
    int64_t top_k, int64_t block_m, double routed_scaling_factor, tvm::ffi::Optional<TensorView> w1_scale_prepared, tvm::ffi::Optional<TensorView> w2_scale_prepared) {
  TVM_FFI_ICHECK(hidden_states.device().device_type == kDLCUDA)
      << "hidden_states must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(hidden_states.device().device_id);
  // Preserve all existing aligned host checks before the first GPU launch.
  (void)CheckInputs(
      hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator,
      top_k, block_m, routed_scaling_factor);
  CheckTensor(topk_ids, dl_int32, 2, true, "topk_ids", "int32");
  CheckSameDevice(topk_ids, hidden_states.device().device_id, "topk_ids");
  CheckShape2(topk_ids, hidden_states.size(0), top_k, "topk_ids");
  AlignAndSeedOutputGeneral(topk_ids, gemm1_weights.size(0) + 1, block_m,
                     sorted_token_ids, expert_ids, num_tokens_post_padded, cumsum_buffer,
                     out, accumulator, true);
  // Run is the unchanged implementation of nvfp4_aligned_moe_op. It consumes
  // exactly the accumulator initialized by the preceding same-stream launch.
  Run(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator,
      top_k, block_m, routed_scaling_factor, w1_scale_prepared, w2_scale_prepared);
}

